def is_valid_sequence(p, n):
    p = list(map(int, p))
    root_candidates = [i for i in range(n) if p[i] == i + 1]
    if len(root_candidates) != 1:
        return False
    root = root_candidates[0]
    visited = set()
    stack = [root]
    while stack:
        u = stack.pop()
        if u in visited:
            return False
        visited.add(u)
        for v in range(n):
            if p[v] == u + 1 and v + 1 != root:
                stack.append(v + 1)
    return len(visited) == n

